TLM.f("Local/zg-05-04",{"officium":"S. Floriani Martyris","rule":[],"fallback":"Commune/C2","from":{"GradualeP":"Commune/C2","Tractus":"Commune/C2"},"sections":{"Introitus":[{"k":"ref","la":"Ps 63:3"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."},{"k":"ref","la":"Ps. 63:2"},{"k":"text","la":"Exáudi, Deus, oratiónem meam cum déprecor: a timóre inimíci éripe ánimam meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."}],"Oratio":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut, qui beáti N. Mártyris tui natalícia cólimus, intercessióne ejus, in tui nóminis amóre roborémur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Petri Apóstoli"},{"k":"ref","la":"1 Petr 1:3-7"},{"k":"text","la":"Benedíctus Deus et Pater Dómini nostri Jesu Christi, qui secúndum misericórdiam suam magnam regenerávit nos in spem vivam, per resurrectiónem Jesu Christi ex mórtuis, in hereditátem incorruptíbilem et incontaminátam et immarcescíbilem, conservátam in cœlis in vobis, qui in virtúte Dei custodímini per fidem in salútem, parátam revelári in témpore novíssimo. In quo exsultábitis, módicum nunc si opórtet contristári in váriis tentatiónibus: ut probátio vestræ fídei multo pretiósior auro [quod per ignem probátur] inveniátur in laudem et glóriam et honórem, in revelatióne Jesu Christi, Dómini nostri."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: étenim veritátem tuam in ecclésia sanctórum. Allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, super caput ejus corónam de lápide pretióso. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: étenim veritátem tuam in ecclésia sanctórum. Allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, super caput ejus corónam de lápide pretióso. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 111:1-2"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 20:3-4"},{"k":"text","la":"Desidérium ánimæ ejus tribuísti ei: et voluntáte labiórum ejus non fraudásti eum."},{"k":"text","la":"Quóniam prævenísti eum in benedictiónibus dulcédinis.","mark":"V"},{"k":"text","la":"Posuísti in cápite ejus corónam de lápide pretióso.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joannes 15:1-7"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Ego sum vitis vera: et Pater meus agrícola est. Omnem pálmitem in me non feréntem fructum, tollet eum: et omnem, qui fert fructum, purgábit eum, ut fructum plus áfferat. Jam vos mundi estis propter sermónem, quem locútus sum vobis. Manéte in me: et ego in vobis. Sicut palmes non potest ferre fructum a semetípso, nisi mánserit in vite: sic nec vos, nisi in me manséritis. Ego sum vitis, vos pálmites: qui manet in me, et ego in eo, hic fert fructum multum: quia sine me nihil potéstis fácere. Si quis in me non mánserit, mittétur foras sicut palmes, et aréscet, et cólligent eum, et in ignem mittent, et ardet. Si manséritis in me, et verba mea in vobis mánserint: quodcúmque voluéritis, petétis, et fiet vobis."}],"Offertorium":[{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: et veritátem tuam in ecclésia sanctórum, allelúja, allelúja."}],"Secreta":[{"k":"text","la":"Munéribus nostris, quǽsumus, Dómine, precibúsque suscéptis: et cœléstibus nos munda mystériis, et cleménter exáudi."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 63:11"},{"k":"text","la":"Lætábitur justus in Dómino, et sperábit in eo: et laudabúntur omnes recti corde, allelúja, allelúja."}],"Postcommunio":[{"k":"text","la":"Da, quǽsumus, Dómine, Deus noster: ut, sicut tuórum commemoratióne Sanctórum temporáli gratulámur offício; ita perpétuo lætémur aspéctu."},{"k":"macro","name":"Per Dominum"}],"Secreta1":[{"k":"text","la":"Múnera tibi, Dómine, dicáta sanctífica: et, intercedénte beáto N. Mártyre tuo atque Pontífice, per éadem nos placátus inténde."},{"k":"macro","name":"Per Dominum"}],"Secreta2":[{"k":"text","la":"Munéribus nostris, quǽsumus, Dómine, precibúsque suscéptis: et cœléstibus nos munda mystériis, et cleménter exáudi."},{"k":"macro","name":"Per Dominum"}],"Secreta3":[{"k":"text","la":"Accépta sit in conspéctu tuo, Dómine, nostra devótio: et ejus nobis fiat supplicatióne salutáris, pro cujus sollemnitáte defértur."},{"k":"macro","name":"Per Dominum"}],"Postcommunio1":[{"k":"text","la":"Hæc nos commúnio, Dómine, purget a crímine: et, intercedénte beáto N. Mártyre tuo atque Pontífice, coeléstis remédii fáciat esse consórtes."},{"k":"macro","name":"Per Dominum"}],"Postcommunio2":[{"k":"text","la":"Da, quǽsumus, Dómine, Deus noster: ut, sicut tuórum commemoratióne Sanctórum temporáli gratulámur offício; ita perpétuo lætémur aspéctu."},{"k":"macro","name":"Per Dominum"}],"Postcommunio3":[{"k":"text","la":"Refécti participatióne múneris sacri, quǽsumus, Dómine, Deus noster: ut, cujus exséquimur cultum, intercedénte beáto N. Mártyre tuo, sentiámus efféctum."},{"k":"macro","name":"Per Dominum"}]},"hr":{"ee67b476e9f36f4d":{"t":"Ps 63, 3, Ps 63, 2\n(Ps 63, 3) Zaštitio si me, Gospodine, od skupa zlikovaca, <i>aleluja</i>,\nod bezbožnoga mnoštva, <i>aleluja</i>, <i>aleluja</i>!\n(Ps 63, 2) Usliši, Gospodine, moju molitvu, jer se tebi molim. Ne daj da se moja duša straši neprijatelja!\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 63, 3) Zaštitio si me, Gospodine, od skupa zlikovaca, <i>aleluja</i>,\nod bezbožnoga mnoštva, <i>aleluja</i>, <i>aleluja</i>!","kn":"(Ps. 63, 2). Štiti me. Bože, od gomile zloitvora. Alelujaod. mnoštva bezbožnoga, aleluja, aleluja. Usliši, Bože, moju molitvu, jer u Tebe se uzdam. izbavi moju dušu do straha neprijateljskoga. Slava Ocu . . . Štiti me . . , <i>aleluja</i>, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 566–567 (snimka 284) (OCR)"},"5516e097ce9135e8":{"kn":"Podaj, molimo, svemogući Bože, da nas, koji svetkujemo rođeni dan blaženoga Florijana, Tvoga mučenika, njegov zagovor ojača u ljubavi Tvoga Imena.\n<i>Po G. n.</i>","knRef":"Kniewald 1942, str. 793"},"5afc73c8f27f27ab":{"kn":"Čitanje poslanice blaženoga Petra apostola (I. 1, 3-7).\nPredragi! Blagoslovljen Bog i Otac Gospodina našega Isusa Krista, koji nas po velikom svojem milosrđu preporodi za živu nadu uskrsnućem Isusa Krista od mrtvih, za baštinu neraspadljivu i neokaljanu i neuvelu, sačuvanu na nebesima za vas, koje čuva po vjeri sila Božja za spasenje da se objavi u posljednje vrijeme. Tada ćete klikovati, iako ste sad malo, ako je potrebno, rastuženi različitim kušnjama, da se prava vaša vjera, mnogo dragocjenija od zlata raspadljivoga, koje se kuša ognjem, nađe na hvalu i slavu i čast u dan objavljenja Isusa Krista, Gospodina našega.","knRef":"Kniewald 1942, str. 566-567"},"157b0d1d6a41242e":{"t":"Ps 88, 6, Ps 20, 4\n<i>Aleluja</i>, <i>aleluja</i>!\n(Ps 88, 6) Nebesa slave tvoja čudesa, Gospodine, a zbor svetih tvoju vjernost, <i>aleluja</i>.\n(Ps 20, 4) Gospodine, okrunio si ga krunom od dragoga kamenja, <i>aleluja</i>.","kn":"Aleluja, aleluja! (Ps. 88, 6). Nebesa slave Tvoja čudesa. Gospodine, i Tvoju vjernost sveti pulc Tvoj, aleluja, aleluja! (Ps. 20, 4). Okrunio si ga, Gospodine, krunom dragoga kamenja, aleluja.","knRef":"Kniewald 1942, str. 804–805 (snimka 403) (OCR)"},"443904ce684f9e74":{"t":"Iv 15, 1-7\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme reče Isus svojim učenicima: Ja sam pravi trs, a moj je Otac vinogradar. Svaku lozu na meni koja ne daje ploda uklonit će, a svaku koja daje plod očistit će da dade još više ploda. Vi ste već čisti radi riječi koju sam vam rekao. Ostanite u meni i ja u vama! Kao što loza sama od sebe ne može dati ploda, ako ne ostane na trsu, tako ni vi ako ne ostanete u meni. Ja sam trs, a vi loze. Tko ostaje u meni i ja u njemu, taj daje mnogo ploda. Bez mene ne možete činiti ništa. Tko ne ostane u meni izbacit će se kao loza koja se osuši, skupi, baca u oganj i izgori. Ako ostanete u meni, ostat će u vama i moje riječi: Štogod budete htjeli, tražite i dat će vam se!","kn":"t Slijedi sv. evanđelje po Ivanu (15, 1-7). U ono vrijeme reče Isus svojim učenicima: Ja sam pravi trs, a moj Otac je vinogradar. Svaku lozu na meni, koja ne daje ploda, uklonit će, a svaku, koja daje plod, očistit će, da dade još više ploda. Vi ste već čisti radi riječi, koju sam vam rekao. Ostanite u meni i ja u vama! Kao što loza sama od sebe ne može dati ploda, ako ne ostane na trsu, tako ni vi, ako ne ostanete na meni. Ja sam trs, a vi loze. Tko ostaje u meni i ja u njemu, taj daje mnogo ploda, jer bez mene ne možete činiti ništa. Tko ne ostane u meni, izbacit će se kao loza, koja se suši, i skupit će je, baciti u oganj 1 izgorjet će. Ako ostanete u meni, ostat će u vama i moje riječi: Štogod budete htjeli, ištite, i dat će vam se!","knRef":"Kniewald 1942, str. 804–805 (snimka 403) (OCR)"},"f6559b160ccd64cf":{"t":"Ps 88, 6\nNebesa slave tvoja čudesa, Gospodine, a zbor svetih tvoju vjernost, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Ps. 88, 6). Nebesa slave čudesa Tvoja, Gospodine, i Tvoju vjernost sveti puk Tvoj, aleluja, aleluja.","knRef":"Kniewald 1942, str. 558–559 (snimka 280) (OCR)"},"0741f87b36183013":{"t":"Primi, molimo, Gospodine, naše darove i molitve te nas nebeskim otajstvima očisti i milostivo usliši.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, Gospodine, naše darove i molitve, te nas blago usliši i očisti nebeskim otajstvima, Po . G. n.","knRef":"Kniewald 1942, str. 572–573 (snimka 287) (OCR)"},"1a0a565aa39e4fe3":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno da tebe, Gospodine, u svako doba, a osobito <i>u ovo</i> svečanije slavimo, kad je Krist žrtvovan, naše vazmeno Janje. On je naime pravo janje koje oduze grijehe svijeta. Svojom smrću on je uništio našu smrt i svojim uskrsnućem obnovio naš život. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"j Uistinu je dostojno i pravedno, pravo i spaso- I doba, ali osobito svečano na - današnji dan, (u ovo vrijeme), kad je žrtvovano naše vazmeno Janje, I Isukrst; jer On je pravo janje, koje je uzelo grijehe : svojim je uskrsnućem obnovio naš ž^vot. Zato pje- I vamo pjesmu Tvoje slave s anđelima i s arkanđe lima, s. prijestolima i s gospodstvima i sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"3042ea87cdaff402":{"t":"Ps 63, 11\nRaduje se pravednik u Gospodinu i pouzdaje se u njega i hvale se svi koji su pravedna srca, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Ps. 63, 11). Veseli se pravednik u Gospodinu i uzda se u njega i raduju se svi, koji su pravedna srca. Aleluja, aleluja.","knRef":"Kniewald 1942, str. 568–569 (snimka 285) (OCR)"},"3b6e3f0bab8b0afc":{"t":"<i>Pomolimo se</i>.\nDaj, molimo, Gospodine Bože naš, da se tako radujemo vječnim gledanjem tvojih svetih kao što se veselimo sjećanjem na njih po vremenitoj službi.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo, Gospodine, Bože naž, kao sto se na zemlji radujemo svetkovini Tvojih svetih, tako da se i u vječnosti veselimo gledajući ih, po G. n.","knRef":"Kniewald 1942, str. 544–545 (snimka 273) (OCR)"},"e3481c16f40c8803":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – On se poslije svojeg uskrsnuća svim svojim učenicima javno ukazao i pred njihovim se očima uzdigao na nebo, da nas učini dionicima svoga božanstva. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Predslovlje: Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospodinu našem, jer On se poslije svoga uskrsnuća očito ukazao svim svojim učenicima 1 njima se na očigled uzđignuo na nebo, da tako, po njegovom daru, budemo zajedničari Božanstva Njegova. I toga radi pjevamo pjesmu slave Tvoje s anđelima i B arkanđelima, s prijestolima i s gospodstvima, sa svom silom nebeske vojske bez prestanka govoreći:","knRef":"Kniewald 1942, str. 336–337 (snimka 169) (OCR)"}}});
